parameters.jsCode:
const lead = $('Normalize Fields').first().json;
let parsed = {};
try {
  const raw = $input.first().json.output || '';
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) { parsed = {}; }
return [{ json: {
  name: lead.name || '',
  phone: lead.phone || '',
  notes: lead.notes || '',
  qualified: parsed.qualified === true,
  reason: typeof parsed.reason === 'string' ? parsed.reason : 'No reason returned'
}}];

